// @prism-system:tool-owned
// Generated by scripts/sync-design-system-apps.mjs from each registered system's source descriptor.
// Do not edit by hand; run `pnpm ds:register <id>` to regenerate.

import type { IconComponent } from "@prism-system/ui-core";

/** The runtime module namespace of one declared design-system icon catalog. */
export type IconModule = Readonly<Record<string, IconComponent>>;

/** A loader that imports one declared icon catalog on demand. */
type IconLoader = () => Promise<unknown>;

/**
 * Literal dynamic imports keyed by design-system id. No icon module is loaded
 * until `loadIcons` selects it. Systems without a declared catalog contribute
 * no import at all.
 */
const iconLoaders: Readonly<Record<string, IconLoader>> = {
  "system-plr": () => import("@prism-system/ui-system-plr/icons"),
};

/** Whether a registered design system declares an icon catalog. */
export function hasIconCatalog(systemId: string): boolean {
  return Object.prototype.hasOwnProperty.call(iconLoaders, systemId);
}

/**
 * Load the declared icon catalog of a registered design system.
 *
 * Only a system with a validated source `icons` declaration resolves; every
 * other id is rejected instead of guessing an import path. The selected module
 * is imported on demand, so opening one catalog never evaluates another.
 */
export async function loadIcons(systemId: string): Promise<IconModule> {
  const loader = Object.prototype.hasOwnProperty.call(iconLoaders, systemId)
    ? iconLoaders[systemId]
    : undefined;
  if (loader === undefined) {
    throw new Error(`Design system ${JSON.stringify(systemId)} declares no icon catalog.`);
  }
  return (await loader()) as IconModule;
}
